      { "b", 1, "On spell tooltips, an aura icon ID that is the same as the spell's own icon is no longer repeated." },
      { "h3", "Chat 0.6.16" },
      { "grp", "Chat History" },
      { "b", 1, "Added whisper tabs: whisper conversations get their own tabs, following the game's New Whispers setting, or all in one Whispers tab (History > Whisper tabs)." },
      { "h3", "Options 0.6.43" },
      { "grp", "Cooldown Manager Warnings" },
